	major: number;
	platform: string;
	architecture: string;
	/** Which source carries it: the running process, the workspace cache, or a version manager. */
	supplier: string;
	/**
	 * Where it sits, relative to the supplier's own root. A record is evidence
	 * and evidence carries no absolute host paths.
