/** A runtime as a host reading carries one. */
function runtime(
	version: string,
	architecture: string,
	supplier: string,
	location: string,
): InstalledRuntime {
	return Object.freeze({
		version,
		major: leadingMajor(version) ?? 0,
		platform: 'darwin',
		architecture,
		supplier,
		location,
	});
